#include <vector>
using namespace std;
long long cnt(vector<int>&a,int l,int r){ if(l>=r) return 0; int m=(l+r)/2; long long c=cnt(a,l,m)+cnt(a,m+1,r);
  vector<int> t; int i=l,j=m+1; while(i<=m&&j<=r){ if(a[i]<=a[j]) t.push_back(a[i++]); else { c+=m-i+1; t.push_back(a[j++]); } }
  while(i<=m) t.push_back(a[i++]); while(j<=r) t.push_back(a[j++]);
  for(int k=0;k<(int)t.size();k++) a[l+k]=t[k]; return c; }
