int n; double W; vector<pair<double,double>> it; double best=0;
double bound(int i,double v,double w){ for(;i<n;i++){ if(w+it[i].second<=W){w+=it[i].second;v+=it[i].first;} else return v+(W-w)*it[i].first/it[i].second; } return v; }
